    Base.RecoveryUIState(self, data)
    if curSelectSuitId then
        local ownEquipSuitIds = self.equipComp:InitOwnEquipSuitIds()
        local ownEquipSuitId  = ownEquipSuitIds[curSelectSuitId]
        Base.OnSuitFilterSelectCompleteListener(self, curSelectSuitId, ownEquipSuitId)

