        self.SuitButtonText.text = name
    end
end

--- override parent
function CardProgressionReclaimEquipmentListNode:UpdateBackpackDataPartList(newId, oldId, part)
    local curPart = Base.GetPart(self)

    --- 选择所有或part相同 则更新
    if curPart == 0 or curPart == part then
        local backpackDataList = Base.GetBackpackDataList(self)
        if oldId > 0 then
            for i, v in ipairs(backpackDataList) do
                if v.id == oldId then
                    table.remove(backpackDataList, i)
                    break
                end
            end
        end

        if newId > 0 then
            local groups = Base.GetGroups(self)
            if part == -1 then
                ---@type EquipmentCoreDojo
                local equipmentCoreDojo = equipComp:GetEquipCoreById(newId)
                local equipmentCoreId = equipmentCoreDojo.equipmentCoreId
                ---@type EquipCoreVo
                local equipCoreVo = cardConfMgr:GetEquipCoreVoById(equipmentCoreId)
                local occupationId = equipCoreVo.occupationId
                local isSatisfy = EquipUtils.CheckEquipFilterCondition({
                    mainAttrId = 0,
                    occupationId = occupationId,
                    playerCardId = equipmentCoreDojo.playerCardId,
                    quality = equipCoreVo.quality
                }, groups, {career = Base.GetCardCareerId(self)})

                if isSatisfy then
                    local data = Base.CreateEquipCoreData(self, equipmentCoreDojo, equipmentCoreId, occupationId, equipCoreVo.quality, equipCoreVo.suitId)
                    table.insert(backpackDataList, data)
                end
            elseif part > 0 then
                ---@type EquipDojo
                local equipDojo = equipComp:GetEquipById(newId)
                local equipmentId = equipDojo.equipmentId
                ---@type EquipVo
                local equipVo = cardConfMgr:GetEquipVoById(equipmentId)

                local isSatisfy = EquipUtils.CheckEquipFilterCondition({
                    mainAttrId = equipDojo.mainAttrId,
                    occupationId = 0,
                    playerCardId = equipDojo.playerCardId,
                    quality = equipVo.rare
                }, groups)
                if isSatisfy then
                    local data = Base.CreateEquipData(self, equipDojo, equipmentId, equipVo.rare, equipVo.part, equipVo.suitId)
                    table.insert(backpackDataList, data)
                end
            end
        end

    end
end

