function CardProgressionReclaimEquipmentListNode:OnClickCellAction(eventData)
    Base.OnClickCellAction(self, eventData)
    local selectedObject   = eventData.selectedObject
    local dataIndex        = selectedObject:GetComponent(IDType).id
    --- 调用父类方法
    local backpackDataList = Base.GetBackpackDataList(self)
    local backpackData     = backpackDataList[dataIndex]
    local backpackDataId   = checkNumber(backpackData.id)

    if checkInt(backpackData.playerCardId) ~= 0 then
        GameUtils.Toast(localize('装备中的物品不可被分解'))
        return 
    end
    if checkInt(backpackData.locked) == 1 then
        GameUtils.Toast(localize('锁定中的物品不可被分解'))
        return
    end


    if self.cellClickCallBack then
        local success = self.cellClickCallBack(backpackDataId, backpackData.part, backpackData.partType, dataIndex)
        if success then
            --- update cell show state
            self.selectId2Res[backpackDataId] = not self.selectId2Res[backpackDataId] == true
            self.selectIndex = dataIndex
        end
    end
end

function CardProgressionReclaimEquipmentListNode:OnLongTapCellAction(eventData)
    Base.OnClickCellAction(self, eventData)
    local selectedObject   = eventData.selectedObject
    local dataIndex        = selectedObject:GetComponent(IDType).id
    --- 调用父类方法
    local backpackDataList = Base.GetBackpackDataList(self)
    local backpackData     = backpackDataList[dataIndex]
    local backpackDataId   = checkNumber(backpackData.id)
    if self.cellLongTapCallback then
        self.cellLongTapCallback(backpackDataId, backpackData.part, backpackData.partType, dataIndex)
    end
end

